+class GHLogCommit {
+  constructor(commit) {
+    this.sha = commit.sha
+    this.sha_short = commit.sha_short
+    this.author = commit.author
+    this.date = commit.date
+    this.message = commit.message
+    this.index = commit.index
+    this.stat_total = commit.stat_total
+  }
+}
+
+export default class GHLogCommits {
+  constructor(commits) {
+    this.commits = commits.map(d => new GHLogCommit(d))
+    this.length = commits.length
+    this.sort()
+  }
+
+  sort() {
+    this.commits.sort((a, b) => a.index - b.index)
+  }
+
+  indexOf(shaShort) {
+    return this.commits.map(d => d.sha_short).indexOf(shaShort) + 1
+  }
+}

@@ -0,0 +1,24 @@
+class GHLogFile {
+  constructor(file) {
+    this.name = file.name
+    this.index = file.index
+    this.commits = file.commits
+  }
+}
+
+export default class GHLogFiles {
+  constructor(files) {
+    this.files = files.map(d => new GHLogFile(d))
+    this.length = this.files.length
+  }
+
+  maxFileNameLength() {
+    const fileLengthList = this.files.map(d => d.name.length)
+    return Math.max(...fileLengthList)
+  }
+
+  indexOf(fileName) {
+    return this.files.map(d => d.name).indexOf(fileName) + 1
+  }
+
+}

